<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span>Material Consumption</span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

    <div class="text-center flex-fill my-4">
        <div v-if="project">
          <h5 class="m-0">
            SITE MATERIAL CONSUMPTION FOR {{ project.project_name }} 
            
          </h5>
        </div>
        <div v-else>
          <h5 class="m-0">SITE MATERIAL CONSUMPTION</h5>
        </div>
    </div>

<div v-if="!project">
<div class="d-flex justify-content-center align-items-center mt-2 flex-wrap toolbar-wrapper my-4">
    <p class="text-dark text-center mb-0 fs-6">
        Please select a project to view material consumption.
    </p>
</div>
   
</div>
   
   <div class="d-flex justify-content-end mt-2">

    <button
      type="button"
      class="btn btn-outline-primary"
      data-bs-toggle="offcanvas"
      data-bs-target="#offcanvasProjects"
      aria-controls="offcanvasProjects"
    >
 Select Project
    </button>
 
</div>


<div v-if="project" >
  <div class="d-flex align-items-center mt-2 flex-wrap toolbar-wrapper">
    <div class="flex-fill toolbar-spacer"></div>

    <div class="d-flex flex-wrap justify-content-end align-items-end gap-2 toolbar-group">

    

      <div class="toolbar-field toolbar-field--date me-3">
        <label class="form-label small mb-1">Start Date</label>
        <input
          type="date"
          class="form-control"
          v-model="start_date"
        >
      </div>

      <div class="toolbar-field toolbar-field--date me-3">
        <label class="form-label small mb-1">End Date</label>
        <input
          type="date"
          class="form-control"
          v-model="end_date"
          :min="start_date"
        >
      </div>

      <div class="toolbar-field toolbar-field--item me-3">
        <label class="form-label small mb-1">
          <span v-if="loading_spinner" v-html="waitIndicator()"></span>
          <span v-else>Select Item</span>
        </label>
        <Multiselect
          v-model="selected_store_item"
          :options="storeItems"
          label="item"
          placeholder="Select an item"
          :searchable="true"
          :allow-empty="false"
          :disabled="loading_spinner"
        />
      </div>

      <div class="toolbar-btn-group">
        <button
          class="btn btn-success mb-2 me-2"
          @click="printMaterialConsumption()"
        >
          <i class="bi bi-printer fs-4"></i>
        </button>

        <button
          class="btn btn-primary mb-2"
          data-bs-toggle="modal"
          data-bs-target="#item-usage-modal"
        >
          <i class="bi bi-plus-square fs-4"></i>
        </button>
      </div>

    </div>
  </div>

  
        <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                 <div v-if="loading_spinner" v-html="tableShimmer()"></div>
                    <div  v-else class="custom-table table3">
                        <v-client-table  
    :data="itemUsage" 
    :columns="itemUsageColumns" 
    :options="table_option">
                           <template #action="props">
                              <a href="javascript:void(0);" 
  title="Edit Item Usage"
  data-bs-toggle="modal" 
  data-bs-target="#item-usage-modal"
  class="text-primary me-2 position-relative"
  @click="openEditModal(props.row)"
>
  <i class="bi bi-pencil-square fs-4"></i>
</a>
             
    
                           </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

</div>



<div class="modal fade mymodal" id="item-usage-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="itemUsageModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="itemUsageModalLabel">
    {{ isEditing ? 'EDIT ITEM USAGE' : 'REGISTER ITEM USAGE' }}
</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="resetForm()"></button>
      </div>
      <form @submit.prevent="registerItemUsage()">
        <div class="modal-body">
                   <div class="row mb-2">
             <div :class="direction ? 'col-md-3' : 'col-md-6'">
            <label class="form-label small">Select Item</label> 
    <Multiselect
        v-model="store_item"
        :options="storeItems"
        label="item"
        placeholder="Select an item"
        :searchable="true"
        :allow-empty="false"
    />
</div>
                           <div  class="col-md-3" >
                            <label class="form-label">Quantity Used , Available : {{ store_item.balance}}</label>
                          <input class="form-control" type="number" step="any" placeholder="Enter Quantity Used "
                           v-model="quantity"
                           :readonly="!store_item"
                          @input="quantity = enforceMax(quantity,store_item.balance,)"
                          required
                          :min="0.1"
                           >
                        </div>
                         
                            <div class="col-md-3">
                          <label class="form-label">Date</label>
                          <input type="date" class="form-control" v-model="date">
                        </div>

                          <div class="mb-12">
    <label for="message-text" class="col-form-label">Description</label>
    <textarea class="form-control" id="message-text" placeholder="Enter Description" v-model="description"></textarea>
  </div>

                      </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="resetForm()" id="close_modal">Close</button>
          <button type="submit" class="btn btn-primary" :disabled="loading">
            <span v-if="loading" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            save
          </button>
        </div>
      </form>
    </div>
  </div>
</div>

<!-- offcanvas start -->
<div class="offcanvas offcanvas-end " data-bs-scroll="true" tabindex="-1" id="offcanvasProjects" aria-labelledby="offcanvasProjectsLabel">
    <div class="offcanvas-header justify-content-between">
        <h5 class="offcanvas-title" id="offcanvasProjectsLabel">SELECT PROJECT</h5>
        <button type="button" class="btn-close" data-bs-dismiss="offcanvas" aria-label="Close"></button>
    </div>
    <div v-if="loadingProjects" v-html="waitIndicator()"></div>
    <div v-else class="offcanvas-body">
        <div class="row">
            <div class="col-12">

                <div class="mb-3">
                    <input
                        type="text"
                        class="form-control"
                        v-model="projectSearch"
                        placeholder="Search project..."
                    >
                </div>

                <div class="list-group text-start" id="list-tab" role="tablist">
    <a
        v-for="proj in searchedProjects"
        :key="proj.project_id"
        @click="project = proj"
        class="list-group-item list-group-item-action"
        :class="{ 'active': project?.project_id === proj.project_id }"
        data-bs-dismiss="offcanvas"
        href="javascript:void(0);"
    >
        {{ proj.project_name }}
        <span class="text-muted small d-block">{{ proj.store_name }}</span>
    </a>
</div>

            </div>
        </div>
    </div>
</div>
<!-- offcanvas ends -->



    </div>

</template>
<script setup>
    import { onMounted, ref, inject, computed, watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    useMeta({ title: 'Material Consumption' });  
    
    const showMessage = inject('showMessage');
    const register_item_usage = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const enforceMax = inject('enforceMax')
    const tableShimmer = inject('tableShimmer');
    const waitIndicator = inject('waitIndicator')
    const loadingSpinner = inject('loadingSpinner'); 
   
    
    const loading_spinner = ref(false);
const itemUsageColumns = ref(['sno', 'item','description','received','issued','balance','date','issuer','action']);
    const name = ref('');
    const quantity = ref('');
    const units = ref('');
    const isEditing = ref(false);
    const register_item_usage_id = ref('');
    const direction = ref('')

const today = new Date().toISOString().split('T')[0];
const start_date = ref(today);
const end_date = ref(today);
    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 51 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

const projectSearch = ref('');
const loadingProjects = ref(false);
    const searchedProjects = computed(() => {
    if (!projectSearch.value) return projects.value;
    const q = projectSearch.value.toLowerCase();
    return projects.value.filter(p =>
        p.project_name?.toLowerCase().includes(q) ||
        p.store_name?.toLowerCase().includes(q)
    );
});

const formatValue = (value) => Number(value) === 0 || value == null ? "---" : value;
const itemUsage = ref([])
const selected_store_item = ref('');
const getItemUsage = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`/copex/report/stores/material-usage`, {
      params: {
        store_id:project.value?.store_id || '',
        store_item_id: selected_store_item.value.id,
        start_date: start_date.value,
        end_date: end_date.value,
      }
    })
    itemUsage.value = response.data.map((item, index) => ({
  ...item,
  sno: index + 1,
  description: item?.remark,
  date: item.date,
  issued: formatValue(item.issued),
  received: formatValue(item.received)
}))
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    loading_spinner.value = false
  }
}
    

const resetForm = () => {
    register_item_usage.value = false;
    isEditing.value = false;
    register_item_usage_id.value = '';
    description.value = '';
    received.value = 0;
    issued.value = 0;
    direction.value = '';
    date.value = '';
};

const openEditModal = (row) => {
    isEditing.value = true;
    register_item_usage_id.value = row;

    const matched = storeItems.value.find(si => si.id === row.store_item_id);

    store_item.value = matched || '';
    direction.value = row.direction;

    issued.value = row.issued === '---' ? 0 : row.issued;
    received.value = row.received === '---' ? 0 : row.received;

    description.value = row.description;
    date.value = row.date;
};

const storeItems = ref([])
const getStoreItems = async () => {
     loading_spinner.value = true
  try {
    const response = await axiosInstance.get(`stocks?store_id=${project.value?.store_id || ''}`)
    storeItems.value = response.data
      .map((item, index) => ({
        ...item,
        SNo: index + 1,
      }))
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    loading_spinner.value = false
  }
}

const store_item = ref('')
const description = ref('')
const date = ref('')
const received = ref('')
const issued = ref('')
const loading = ref(false)


const registerItemUsage = async () => {
    loading.value = true;
    const payload = {
        store_item_id: store_item.value.id,
        issued: issued.value,
        received: received.value,
        remark: description.value,
        date: date.value,
        bincard_item_id: register_item_usage_id.value.id,
        issuer_id: JSON.parse(localStorage.getItem("user")).id,
    };


    try {
        if (isEditing.value) {
            await axiosInstance.put(`bin-cards/${register_item_usage_id.value.bin_card_id}`, payload);
            showMessage('Item Usage Updated');
        } else {
            await axiosInstance.post('bin-cards', payload);
            showMessage('Item Registered');
        }
        document.getElementById('close_modal').click();
        getItemUsage();
        resetForm();
    } catch (error) {
        console.log(error);
        showError(error.message);
    } finally {
        loading.value = false;
    }
};

watch(start_date, () => {
    getItemUsage();
});

watch(end_date, () => {
    getItemUsage();
});

watch(selected_store_item, () => {
        getItemUsage();
});



const printMaterialConsumption = async () => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const itemName = store_item.value?.name || 'All Items';

    const totalReceived = itemUsage.value.reduce((sum, row) => {
      const val = parseFloat(row.received) || 0;
      return sum + val;
    }, 0);

    const totalIssued = itemUsage.value.reduce((sum, row) => {
      const val = parseFloat(row.issued) || 0;
      return sum + val;
    }, 0);

    

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Material Consumption Report</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 13px; }
  .text-style { font-family: 'Courier New', monospace; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 20px; margin: 10px 0; }
  .meta { display: flex; justify-content: space-between; margin: 10px 0; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 0.5px solid #000; padding: 6px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  hr { border: 0; border-top: 0.5px solid #000; margin: 0px 0; }
  @media print { body { margin: 10mm; } }
</style>
</head>
<body>

<div class="company-title text-style">
<i>
<h1>COPEX CONTRACTORS CO.LTD</h1>
<div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
<div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
<div><b>Email:</b> info@copexcontractors.co.tz</div>
<div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
</i>
</div>

<hr style="margin-top:20px">

<div class="title text-style">
  MATERIAL CONSUMPTION REPORT
</div>

<hr>

<div class="meta text-style">
  <div><b>Item:</b> ${itemName}</div>
  <div><b>Period:</b> ${start_date.value} to ${end_date.value}</div>
</div>

<table>
  <thead>
    <tr>
      <th>No.</th>
      <th>Item</th>
      <th>Description</th>
      <th class="text-right">Received</th>
      <th class="text-right">Issued</th>
      <th class="text-right">Balance</th>
      <th>Date</th>
    </tr>
  </thead>
  <tbody>
    ${itemUsage.value.map((row, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${row.item || '--'}</td>
      <td>${row.description || '--'}</td>
      <td class="text-right">${row.received || '--'}</td>
      <td class="text-right">${row.issued || '--'}</td>
      <td class="text-right">${row.balance || '--'}</td>
      <td>${row.date || '--'}</td>
    </tr>
    `).join('')}
    <tr>
      <td colspan="3" class="text-right"><strong>TOTAL:</strong></td>
      <td class="text-right"><strong>${totalReceived}</strong></td>
      <td class="text-right"><strong>${totalIssued}</strong></td>
      <td colspan="2"></td>
    </tr>
  </tbody>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
};


const projects = ref([]);
const project = ref(null);
const getProjects = async () => {
    try {
        const response = await axiosInstance.get('stores-projects');

        projects.value = response.data.map(item => ({
                ...item,
            }));
    } catch (error) {
        showError(error.message);
        console.log(error);
    }
};
watch(project, () => {
    getStoreItems();
        getItemUsage();
});
    onMounted(() => {
        getItemUsage ();
         getProjects();
                 // Open the offcanvas modal on mount
  const offcanvasElement = document.getElementById('offcanvasProjects');
  if (offcanvasElement) {
    const offcanvas = new bootstrap.Offcanvas(offcanvasElement);
    offcanvas.show();
  }
    });
</script>
<style scoped>
/* Desktop / large screens: preserve existing fixed-width layout */
.toolbar-field--project { width: 300px; }
.toolbar-field--date    { width: 130px; }
.toolbar-field--item    { width: 200px; }

/* Only touch layout below lg breakpoint (991.98px) */
@media (max-width: 991.98px) {
  .toolbar-spacer {
    display: none; /* no need for the pushing spacer once we stack */
  }

  .toolbar-group {
    width: 100%;
    flex-direction: column;
    align-items: stretch;
  }

  .toolbar-field--project,
  .toolbar-field--date,
  .toolbar-field--item {
    width: 100% !important;
    margin-right: 0 !important;
  }

  .toolbar-btn-group {
    display: flex;
    gap: 0.5rem;
    width: 100%;
  }

  .toolbar-btn-group .btn {
    flex: 1;
    margin-bottom: 0 !important;
  }
}
</style>